1	// Package settings provides configuration loading for Entire.
2	// This package is separate from cli to allow strategy package to import it
3	// without creating an import cycle (cli imports strategy).
4	package settings
5	
6	import (
7		"bytes"
8		"context"
9		"encoding/json"
10		"fmt"
11		"os"
12		"path/filepath"
13		"strings"
14	
15		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
16		"github.com/entireio/cli/cmd/entire/cli/paths"
17	)
18	
19	const (
20		// EntireSettingsFile is the path to the Entire settings file
21		EntireSettingsFile = ".entire/settings.json"
22		// EntireSettingsLocalFile is the path to the local settings override file (not committed)
23		EntireSettingsLocalFile = ".entire/settings.local.json"
24	)
25	
26	// Commit linking mode constants.
27	const (
28		// CommitLinkingAlways auto-links commits to sessions without prompting.
29		CommitLinkingAlways = "always"
30		// CommitLinkingPrompt prompts the user on each commit (default for existing users).
31		CommitLinkingPrompt = "prompt"
32	)
33	
34	// EntireSettings represents the .entire/settings.json configuration
35	type EntireSettings struct {
36	
37		// Enabled indicates whether Entire is active. When false, CLI commands
38		// show a disabled message and hooks exit silently. Defaults to true.
39		Enabled bool `json:"enabled"`
40	
41		// LocalDev indicates whether to use "go run" instead of the "entire" binary
42		// This is used for development when the binary is not installed
43		LocalDev bool `json:"local_dev,omitempty"`
44	
45		// LogLevel sets the logging verbosity (debug, info, warn, error).
46		// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
47		// Defaults to "info".
48		LogLevel string `json:"log_level,omitempty"`
49	
50		// StrategyOptions contains strategy-specific configuration
51		StrategyOptions map[string]any `json:"strategy_options,omitempty"`
52	
53		// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
54		// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
55		// that don't source shell profiles and can't find "entire" on PATH.
56		AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`
57	
58		// Telemetry controls anonymous usage analytics.
59		// nil = not asked yet (show prompt), true = opted in, false = opted out
60		Telemetry *bool `json:"telemetry,omitempty"`
61	
62		// Redaction configures PII redaction behavior for transcripts and metadata.
63		Redaction *RedactionSettings `json:"redaction,omitempty"`
64	
65		// CommitLinking controls how commits are linked to agent sessions.
66		// "always" = auto-link without prompting, "prompt" = ask on each commit.
67		// Defaults to "prompt" (preserves existing user behavior).
68		CommitLinking string `json:"commit_linking,omitempty"`
69	
70		// ExternalAgents enables discovery and registration of external agent
71		// plugins (entire-agent-* binaries on $PATH). Defaults to false.
72		ExternalAgents bool `json:"external_agents,omitempty"`
73	
74		// Deprecated: no longer used. Exists to tolerate old settings files
75		// that still contain "strategy": "auto-commit" or similar.
76		Strategy string `json:"strategy,omitempty"`
77	}
78	
79	// RedactionSettings configures redaction behavior beyond the default secret detection.
80	type RedactionSettings struct {
81		PII *PIISettings `json:"pii,omitempty"`
82	}
83	
84	// PIISettings configures PII detection categories.
85	// When Enabled is true, email and phone default to true; address defaults to false.
86	type PIISettings struct {
87		Enabled        bool              `json:"enabled"`
88		Email          *bool             `json:"email,omitempty"`
89		Phone          *bool             `json:"phone,omitempty"`
90		Address        *bool             `json:"address,omitempty"`
91		CustomPatterns map[string]string `json:"custom_patterns,omitempty"`
92	}
93	
94	// GetCommitLinking returns the effective commit linking mode.
95	// Returns the explicit value if set, otherwise defaults to "prompt"
96	// to preserve existing user behavior.
97	func (s *EntireSettings) GetCommitLinking() string {
98		if s.CommitLinking != "" {
99			return s.CommitLinking
100		}
101		return CommitLinkingPrompt
102	}
103	
104	// Load loads the Entire settings from .entire/settings.json,
105	// then applies any overrides from .entire/settings.local.json if it exists.
106	// Returns default settings if neither file exists.
107	// Works correctly from any subdirectory within the repository.
108	func Load(ctx context.Context) (*EntireSettings, error) {
109		// Get absolute paths for settings files
110		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
111		if err != nil {
112			settingsFileAbs = EntireSettingsFile // Fallback to relative
113		}
114		localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
115		if err != nil {
116			localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
117		}
118	
119		// Load base settings
120		settings, err := loadFromFile(settingsFileAbs)
121		if err != nil {
122			return nil, fmt.Errorf("reading settings file: %w", err)
123		}
124	
125		// Apply local overrides if they exist
126		localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
127		if err != nil {
128			if !os.IsNotExist(err) {
129				return nil, fmt.Errorf("reading local settings file: %w", err)
130			}
131			// Local file doesn't exist, continue without overrides
132		} else {
133			if err := mergeJSON(settings, localData); err != nil {
134				return nil, fmt.Errorf("merging local settings: %w", err)
135			}
136		}
137	
138		return settings, nil
139	}
140	
141	// LoadFromFile loads settings from a specific file path without merging local overrides.
142	// Returns default settings if the file doesn't exist.
143	// Use this when you need to display individual settings files separately.
144	func LoadFromFile(filePath string) (*EntireSettings, error) {
145		return loadFromFile(filePath)
146	}
147	
148	// loadFromFile loads settings from a specific file path.
149	// Returns default settings if the file doesn't exist.
150	func loadFromFile(filePath string) (*EntireSettings, error) {
151		settings := &EntireSettings{
152			Enabled: true, // Default to enabled
153		}
154	
155		data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
156		if err != nil {
157			if os.IsNotExist(err) {
158				return settings, nil
159			}
160			return nil, fmt.Errorf("%w", err)
161		}
162	
163		dec := json.NewDecoder(bytes.NewReader(data))
164		dec.DisallowUnknownFields()
165		if err := dec.Decode(settings); err != nil {
166			return nil, fmt.Errorf("parsing settings file: %w", err)
167		}
168	
169		// Validate commit_linking if set
170		if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
171			return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
172		}
173	
174		return settings, nil
175	}
176	
177	// mergeJSON merges JSON data into existing settings.
178	// Only non-zero values from the JSON override existing settings.
179	func mergeJSON(settings *EntireSettings, data []byte) error {
180		// First, validate that there are no unknown keys using strict decoding
181		dec := json.NewDecoder(bytes.NewReader(data))
182		dec.DisallowUnknownFields()
183		var temp EntireSettings
184		if err := dec.Decode(&temp); err != nil {
185			return fmt.Errorf("parsing JSON: %w", err)
186		}
187	
188		// Parse into a map to check which fields are present
189		var raw map[string]json.RawMessage
190		if err := json.Unmarshal(data, &raw); err != nil {
191			return fmt.Errorf("parsing JSON: %w", err)
192		}
193	
194		// Override enabled if present
195		if enabledRaw, ok := raw["enabled"]; ok {
196			var e bool
197			if err := json.Unmarshal(enabledRaw, &e); err != nil {
198				return fmt.Errorf("parsing enabled field: %w", err)
199			}
200			settings.Enabled = e
201		}
202	
203		// Override local_dev if present
204		if localDevRaw, ok := raw["local_dev"]; ok {
205			var ld bool
206			if err := json.Unmarshal(localDevRaw, &ld); err != nil {
207				return fmt.Errorf("parsing local_dev field: %w", err)
208			}
209			settings.LocalDev = ld
210		}
211	
212		// Override absolute_git_hook_path if present
213		if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
214			var ahp bool
215			if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
216				return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
217			}
218			settings.AbsoluteGitHookPath = ahp
219		}
220	
221		// Override log_level if present and non-empty
222		if logLevelRaw, ok := raw["log_level"]; ok {
223			var ll string
224			if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
225				return fmt.Errorf("parsing log_level field: %w", err)
226			}
227			if ll != "" {
228				settings.LogLevel = ll
229			}
230		}
231	
232		// Merge strategy_options if present
233		if optionsRaw, ok := raw["strategy_options"]; ok {
234			var opts map[string]any
235			if err := json.Unmarshal(optionsRaw, &opts); err != nil {
236				return fmt.Errorf("parsing strategy_options field: %w", err)
237			}
238			if settings.StrategyOptions == nil {
239				settings.StrategyOptions = opts
240			} else {
241				for k, v := range opts {
242					settings.StrategyOptions[k] = v
243				}
244			}
245		}
246	
247		// Override telemetry if present
248		if telemetryRaw, ok := raw["telemetry"]; ok {
249			var t bool
250			if err := json.Unmarshal(telemetryRaw, &t); err != nil {
251				return fmt.Errorf("parsing telemetry field: %w", err)
252			}
253			settings.Telemetry = &t
254		}
255	
256		// Merge redaction sub-fields if present (field-level, not wholesale replace).
257		if redactionRaw, ok := raw["redaction"]; ok {
258			if settings.Redaction == nil {
259				settings.Redaction = &RedactionSettings{}
260			}
261			if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
262				return fmt.Errorf("parsing redaction field: %w", err)
263			}
264		}
265	
266		// Override commit_linking if present and non-empty
267		if commitLinkingRaw, ok := raw["commit_linking"]; ok {
268			var cl string
269			if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
270				return fmt.Errorf("parsing commit_linking field: %w", err)
271			}
272			if cl != "" {
273				switch cl {
274				case CommitLinkingAlways, CommitLinkingPrompt:
275					settings.CommitLinking = cl
276				default:
277					return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
278				}
279			}
280		}
281	
282		// Override external_agents if present
283		if externalAgentsRaw, ok := raw["external_agents"]; ok {
284			var ea bool
285			if err := json.Unmarshal(externalAgentsRaw, &ea); err != nil {
286				return fmt.Errorf("parsing external_agents field: %w", err)
287			}
288			settings.ExternalAgents = ea
289		}
290	
291		return nil
292	}
293	
294	// mergeRedaction merges redaction overrides into existing RedactionSettings.
295	// Only fields present in the override JSON are applied.
296	func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
297		var raw map[string]json.RawMessage
298		if err := json.Unmarshal(data, &raw); err != nil {
299			return fmt.Errorf("parsing redaction: %w", err)
300		}
301		if piiRaw, ok := raw["pii"]; ok {
302			if dst.PII == nil {
303				dst.PII = &PIISettings{}
304			}
305			if err := mergePIISettings(dst.PII, piiRaw); err != nil {
306				return err
307			}
308		}
309		return nil
310	}
311	
312	// mergePIISettings merges PII overrides into existing PIISettings.
313	// Only fields present in the override JSON are applied; missing fields
314	// are preserved from the base settings.
315	func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
316		var raw map[string]json.RawMessage
317		if err := json.Unmarshal(data, &raw); err != nil {
318			return fmt.Errorf("parsing pii: %w", err)
319		}
320		if v, ok := raw["enabled"]; ok {
321			if err := json.Unmarshal(v, &dst.Enabled); err != nil {
322				return fmt.Errorf("parsing pii.enabled: %w", err)
323			}
324		}
325		if v, ok := raw["email"]; ok {
326			var b bool
327			if err := json.Unmarshal(v, &b); err != nil {
328				return fmt.Errorf("parsing pii.email: %w", err)
329			}
330			dst.Email = &b
331		}
332		if v, ok := raw["phone"]; ok {
333			var b bool
334			if err := json.Unmarshal(v, &b); err != nil {
335				return fmt.Errorf("parsing pii.phone: %w", err)
336			}
337			dst.Phone = &b
338		}
339		if v, ok := raw["address"]; ok {
340			var b bool
341			if err := json.Unmarshal(v, &b); err != nil {
342				return fmt.Errorf("parsing pii.address: %w", err)
343			}
344			dst.Address = &b
345		}
346		if v, ok := raw["custom_patterns"]; ok {
347			var cp map[string]string
348			if err := json.Unmarshal(v, &cp); err != nil {
349				return fmt.Errorf("parsing pii.custom_patterns: %w", err)
350			}
351			if dst.CustomPatterns == nil {
352				dst.CustomPatterns = cp
353			} else {
354				for k, val := range cp {
355					dst.CustomPatterns[k] = val
356				}
357			}
358		}
359		return nil
360	}
361	
362	// IsSetUp returns true if Entire has been set up in the current repository.
363	// This checks if .entire/settings.json exists.
364	// Use this to avoid creating files/directories in repos where Entire was never enabled.
365	func IsSetUp(ctx context.Context) bool {
366		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
367		if err != nil {
368			return false
369		}
370		_, err = os.Stat(settingsFileAbs)
371		return err == nil
372	}
373	
374	// IsSetUpAny returns true if Entire has been set up in the current repository,
375	// checking both .entire/settings.json and .entire/settings.local.json.
376	// Use this to detect any prior setup, even if only local settings exist.
377	func IsSetUpAny(ctx context.Context) bool {
378		if IsSetUp(ctx) {
379			return true
380		}
381		localFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
382		if err != nil {
383			return false
384		}
385		_, err = os.Lstat(localFileAbs)
386		return err == nil
387	}
388	
389	// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
390	// This checks if .entire/settings.json exists AND has enabled: true.
391	// Use this for hooks that should be no-ops when Entire is not active.
392	func IsSetUpAndEnabled(ctx context.Context) bool {
393		if !IsSetUp(ctx) {
394			return false
395		}
396		s, err := Load(ctx)
397		if err != nil {
398			return false
399		}
400		return s.Enabled
401	}
402	
403	// IsCheckpointsV2Enabled checks if checkpoints v2 is enabled in settings.
404	// Returns false by default if settings cannot be loaded or the key is missing.
405	func IsCheckpointsV2Enabled(ctx context.Context) bool {
406		settings, err := Load(ctx)
407		if err != nil {
408			return false
409		}
410		return settings.IsCheckpointsV2Enabled()
411	}
412	
413	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled in settings.
414	// Returns false by default if settings cannot be loaded or flags are missing.
415	func IsPushV2RefsEnabled(ctx context.Context) bool {
416		s, err := Load(ctx)
417		if err != nil {
418			return false
419		}
420		return s.IsPushV2RefsEnabled()
421	}
422	
423	// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
424	// Returns false by default if settings cannot be loaded or the key is missing.
425	func IsSummarizeEnabled(ctx context.Context) bool {
426		settings, err := Load(ctx)
427		if err != nil {
428			return false
429		}
430		return settings.IsSummarizeEnabled()
431	}
432	
433	// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
434	func (s *EntireSettings) IsSummarizeEnabled() bool {
435		if s.StrategyOptions == nil {
436			return false
437		}
438		summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
439		if !ok {
440			return false
441		}
442		enabled, ok := summarizeOpts["enabled"].(bool)
443		if !ok {
444			return false
445		}
446		return enabled
447	}
448	
449	// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
450	// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
451	type CheckpointRemoteConfig struct {
452		Provider string // e.g., "github"
453		Repo     string // e.g., "org/checkpoints-repo"
454	}
455	
456	// Owner returns the owner portion of the repo field (before the slash).
457	// Returns empty string if the repo field doesn't contain a slash.
458	func (c *CheckpointRemoteConfig) Owner() string {
459		parts := strings.SplitN(c.Repo, "/", 2)
460		if len(parts) < 2 {
461			return ""
462		}
463		return parts[0]
464	}
465	
466	// GetCheckpointRemote returns the configured checkpoint remote.
467	// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
468	// Returns nil if not configured, wrong type, or missing required fields.
469	func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
470		if s.StrategyOptions == nil {
471			return nil
472		}
473		val, ok := s.StrategyOptions["checkpoint_remote"]
474		if !ok {
475			return nil
476		}
477		m, ok := val.(map[string]any)
478		if !ok {
479			return nil
480		}
481		provider, providerOK := m["provider"].(string)
482		repo, repoOK := m["repo"].(string)
483		if !providerOK || !repoOK || provider == "" || repo == "" {
484			return nil
485		}
486		if !strings.Contains(repo, "/") {
487			return nil
488		}
489		return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
490	}
491	
492	// IsCheckpointsV2Enabled checks if checkpoints v2 (dual-write to refs/entire/) is enabled.
493	// Returns false by default if the key is missing or not a bool.
494	func (s *EntireSettings) IsCheckpointsV2Enabled() bool {
495		if s.StrategyOptions == nil {
496			return false
497		}
498		val, ok := s.StrategyOptions["checkpoints_v2"].(bool)
499		return ok && val
500	}
501	
502	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled.
503	// Requires both checkpoints_v2 and push_v2_refs to be true.
504	func (s *EntireSettings) IsPushV2RefsEnabled() bool {
505		if !s.IsCheckpointsV2Enabled() {
506			return false
507		}
508		if s.StrategyOptions == nil {
509			return false
510		}
511		val, ok := s.StrategyOptions["push_v2_refs"].(bool)
512		return ok && val
513	}
514	
515	// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
516	// Returns true if push_sessions is explicitly set to false.
517	func (s *EntireSettings) IsPushSessionsDisabled() bool {
518		if s.StrategyOptions == nil {
519			return false
520		}
521		val, exists := s.StrategyOptions["push_sessions"]
522		if !exists {
523			return false
524		}
525		if boolVal, ok := val.(bool); ok {
526			return !boolVal // disabled = !push_sessions
527		}
528		return false
529	}
530	
531	// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
532	// Returns false by default if settings cannot be loaded or the key is missing.
533	func IsExternalAgentsEnabled(ctx context.Context) bool {
534		s, err := Load(ctx)
535		if err != nil {
536			return false
537		}
538		return s.ExternalAgents
539	}
540	
541	// Save saves the settings to .entire/settings.json.
542	func Save(ctx context.Context, settings *EntireSettings) error {
543		return saveToFile(ctx, settings, EntireSettingsFile)
544	}
545	
546	// SaveLocal saves the settings to .entire/settings.local.json.
547	func SaveLocal(ctx context.Context, settings *EntireSettings) error {
548		return saveToFile(ctx, settings, EntireSettingsLocalFile)
549	}
550	
551	// saveToFile saves settings to the specified file path.
552	func saveToFile(ctx context.Context, settings *EntireSettings, filePath string) error {
553		// Get absolute path for the file
554		filePathAbs, err := paths.AbsPath(ctx, filePath)
555		if err != nil {
556			filePathAbs = filePath // Fallback to relative
557		}
558	
559		// Ensure directory exists
560		dir := filepath.Dir(filePathAbs)
561		if err := os.MkdirAll(dir, 0o750); err != nil {
562			return fmt.Errorf("creating settings directory: %w", err)
563		}
564	
565		data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
566		if err != nil {
567			return fmt.Errorf("marshaling settings: %w", err)
568		}
569	
570		//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
571		if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
572			return fmt.Errorf("writing settings file: %w", err)
573		}
574		return nil
575	}
576	
