export async function fetchFileAtCommit(
  repoFullName: string,
  path: string,
  sha: string,
  accessToken?: string,
): Promise<string | null> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github.raw+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
  }

  if (accessToken) {
    headers.Authorization = `Bearer ${accessToken}`
  }

  const encodedPath = path.split("/").map(encodeURIComponent).join("/")
  const response = await fetch(
    `${GITHUB_API}/repos/${repoFullName}/contents/${encodedPath}?ref=${sha}`,
    { headers },
  )

  if (!response.ok) {
    response.body?.cancel()
    if (response.status === 404) {
      return null
    }
    throw new Error(`Failed to fetch file: ${response.status}`)
  }

  return response.text()
}
```

The function:
- Uses GitHub REST API: `GET /repos/{owner}/{repo}/contents/{path}?ref={ref}`
- Uses raw content accept header: `Accept: application/vnd.github.raw+json`
- Returns raw file content as text
- Returns null if the file doesn't exist (404)

