31	func newAttachCmd() *cobra.Command {
32		var (
33			force     bool
34			agentFlag string
35		)
36		cmd := &cobra.Command{
37			Use:   "attach <session-id>",
38			Short: "Attach an existing agent session",
39			Long: `Attach an existing agent session that wasn't captured by hooks.
40	
41	This creates a checkpoint from the session's transcript and links it to the
42	last commit. Use this when hooks failed to fire or weren't installed when
43	the session started, or to attach a research session.
44	
45	If the last commit already has a checkpoint, the session is added to it.
46	Otherwise a new checkpoint is created.
47	
48	Supported agents: claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid`,
49			RunE: func(cmd *cobra.Command, args []string) error {
50				if len(args) != 1 {
51					return cmd.Help()
52				}
53				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
54					return nil
55				}
56				agentName := types.AgentName(agentFlag)
57				return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
58			},
59		}
60		cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
61		cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid)")
62		return cmd
63	}
