178	// getHeadCommit returns the HEAD commit object.
179	func getHeadCommit(repo *git.Repository) (*object.Commit, error) {
180		headRef, err := repo.Head()
181		if err != nil {
182			return nil, fmt.Errorf("failed to get HEAD: %w", err)
183		}
184		commit, err := repo.CommitObject(headRef.Hash())
185		if err != nil {
186			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
187		}
188		return commit, nil
189	}
190	
191	// resolveCheckpointID returns the checkpoint ID to use for the attach.
192	// If HEAD already has an Entire-Checkpoint trailer, reuses that ID (the session
193	// gets added as an additional session in the existing checkpoint).
194	// Otherwise generates a new ID.
195	func resolveCheckpointID(headCommit *object.Commit) (id.CheckpointID, bool) {
196		existing := trailers.ParseAllCheckpoints(headCommit.Message)
197		if len(existing) > 0 {
198			return existing[len(existing)-1], true
199		}
200	
201		cpID, err := id.Generate()
202		if err != nil {
203			// Generation only fails if crypto/rand fails — extremely unlikely.
204			// Fall back to empty which will cause WriteCommitted to fail with a clear error.
205			return id.EmptyCheckpointID, false
206		}
207		return cpID, false
208	}
