210	// saveAttachSessionState creates or updates the session state file for the attached session.
211	// If existingState is non-nil, it is updated in place (avoids a redundant disk load).
212	func saveAttachSessionState(ctx context.Context, existingState *session.State, sessionID string, agentType types.AgentType, transcriptPath string, checkpointID id.CheckpointID, meta transcriptMetadata, tokenUsage *agent.TokenUsage) error {
213		stateStore, err := session.NewStateStore(ctx)
214		if err != nil {
215			return fmt.Errorf("failed to open session store: %w", err)
216		}
217	
218		now := time.Now()
219		state := existingState
220		if state == nil {
221			state = &session.State{
222				SessionID: sessionID,
223				StartedAt: now,
224			}
225		}
226	
227		state.CLIVersion = versioninfo.Version
228		state.AttachedManually = true
229		state.AgentType = agentType
230		state.TranscriptPath = transcriptPath
231		state.LastCheckpointID = checkpointID
232		state.Phase = session.PhaseEnded
233		state.LastInteractionTime = &now
234		if meta.TurnCount > 0 {
235			state.SessionTurnCount = meta.TurnCount
236		}
237		if meta.Model != "" {
238			state.ModelName = meta.Model
239		}
240		if meta.FirstPrompt != "" {
241			state.LastPrompt = meta.FirstPrompt
242		}
243		if tokenUsage != nil {
244			state.TokenUsage = tokenUsage
245		}
246	
247		if err := stateStore.Save(ctx, state); err != nil {
248			return fmt.Errorf("failed to save session state: %w", err)
249		}
250		return nil
251	}
