26	// pushRefIfNeeded pushes a custom ref to the given target if it exists locally.
27	// Custom refs (under refs/entire/) don't have remote-tracking refs, so there's
28	// no "has unpushed" optimization — we always attempt the push and let git handle
29	// the no-op case.
30	func pushRefIfNeeded(ctx context.Context, target string, refName plumbing.ReferenceName) error {
31		repo, err := OpenRepository(ctx)
32		if err != nil {
33			return nil //nolint:nilerr // Hook must be silent on failure
34		}
35	
36		if _, err := repo.Reference(refName, true); err != nil {
37			return nil //nolint:nilerr // Ref doesn't exist locally, nothing to push
38		}
39	
40		return doPushRef(ctx, target, refName)
41	}
42	
43	// tryPushRef attempts to push a custom ref using an explicit refspec.
44	func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
45		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
46		defer cancel()
47	
48		// Use --no-verify to prevent recursive hook calls (this runs inside pre-push)
49		refSpec := fmt.Sprintf("%s:%s", refName, refName)
50		cmd := CheckpointGitCommand(ctx, target, "push", "--no-verify", target, refSpec)
51	
52		output, err := cmd.CombinedOutput()
53		if err != nil {
54			if strings.Contains(string(output), "non-fast-forward") ||
55				strings.Contains(string(output), "rejected") {
56				return errors.New("non-fast-forward")
57			}
58			return fmt.Errorf("push failed: %s", output)
59		}
60		return nil
61	}
62	
63	// doPushRef pushes a custom ref with fetch+merge recovery on conflict.
64	func doPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
65		displayTarget := target
66		if isURL(target) {
67			displayTarget = "checkpoint remote"
68		}
69	
70		shortRef := shortRefName(refName)
71		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
72		stop := startProgressDots(os.Stderr)
73	
74		if err := tryPushRef(ctx, target, refName); err == nil {
75			stop(" done")
76			return nil
77		}
78		stop("")
79	
80		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", shortRef)
81		stop = startProgressDots(os.Stderr)
82	
83		if err := fetchAndMergeRef(ctx, target, refName); err != nil {
84			stop("")
85			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", shortRef, err)
86			printCheckpointRemoteHint(target)
87			return nil
88		}
89		stop(" done")
90	
91		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
92		stop = startProgressDots(os.Stderr)
93	
94		if err := tryPushRef(ctx, target, refName); err != nil {
95			stop("")
96			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", shortRef, err)
97			printCheckpointRemoteHint(target)
98		} else {
99			stop(" done")
100		}
101	
102		return nil
103	}
104	
105	// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
106	// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
107	//
108	// For /full/current: if the remote has archived generations not present locally,
109	// another machine rotated. In that case, local data is merged into the latest
110	// archived generation instead of into /full/current (see handleRotationConflict).
111	func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
112		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
113		defer cancel()
114	
115		// Fetch to a temp ref
116		tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
117		tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
118		refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
119	
120		fetchCmd := CheckpointGitCommand(ctx, target, "fetch", target, refSpec)
121		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
122		if output, err := fetchCmd.CombinedOutput(); err != nil {
123			return fmt.Errorf("fetch failed: %s", output)
124		}
125	
126		repo, err := OpenRepository(ctx)
127		if err != nil {
128			return fmt.Errorf("failed to open repository: %w", err)
129		}
130		defer func() {
131			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
132		}()
133	
134		// Check for rotation conflict on /full/current
135		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
136			remoteOnlyArchives, detectErr := detectRemoteOnlyArchives(ctx, target, repo)
137			if detectErr == nil && len(remoteOnlyArchives) > 0 {
138				return handleRotationConflict(ctx, target, repo, refName, tmpRefName, remoteOnlyArchives)
139			}
140		}
141	
142		// Standard tree merge (no rotation detected)
143		localRef, err := repo.Reference(refName, true)
144		if err != nil {
145			return fmt.Errorf("failed to get local ref: %w", err)
146		}
147		localCommit, err := repo.CommitObject(localRef.Hash())
148		if err != nil {
149			return fmt.Errorf("failed to get local commit: %w", err)
150		}
151		localTree, err := localCommit.Tree()
152		if err != nil {
153			return fmt.Errorf("failed to get local tree: %w", err)
154		}
155	
156		remoteRef, err := repo.Reference(tmpRefName, true)
157		if err != nil {
158			return fmt.Errorf("failed to get remote ref: %w", err)
159		}
160		remoteCommit, err := repo.CommitObject(remoteRef.Hash())
161		if err != nil {
162			return fmt.Errorf("failed to get remote commit: %w", err)
163		}
164		remoteTree, err := remoteCommit.Tree()
165		if err != nil {
166			return fmt.Errorf("failed to get remote tree: %w", err)
167		}
168	
169		entries := make(map[string]object.TreeEntry)
170		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
171			return fmt.Errorf("failed to flatten local tree: %w", err)
172		}
173		if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
174			return fmt.Errorf("failed to flatten remote tree: %w", err)
175		}
176	
177		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
178		if err != nil {
179			return fmt.Errorf("failed to build merged tree: %w", err)
180		}
181	
182		mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
183			[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
184			"Merge remote "+shortRefName(refName))
185		if err != nil {
186			return fmt.Errorf("failed to create merge commit: %w", err)
187		}
188	
189		newRef := plumbing.NewHashReference(refName, mergeCommitHash)
190		if err := repo.Storer.SetReference(newRef); err != nil {
191			return fmt.Errorf("failed to update ref: %w", err)
192		}
193	
194		return nil
195	}
196	
197	// detectRemoteOnlyArchives discovers archived generation refs on the remote
198	// that don't exist locally. Returns them sorted ascending (oldest first).
199	func detectRemoteOnlyArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
200		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
201		defer cancel()
202	
203		cmd := CheckpointGitCommand(ctx, target, "ls-remote", target, paths.V2FullRefPrefix+"*")
204		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
205		output, err := cmd.Output()
206		if err != nil {
207			return nil, fmt.Errorf("ls-remote failed: %w", err)
208		}
209	
210		var remoteOnly []string
211		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
212			if line == "" {
213				continue
214			}
215			parts := strings.Fields(line)
216			if len(parts) < 2 {
217				continue
218			}
219			refName := parts[1]
220			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
221			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
222				continue
223			}
224			// Only check for existence, not hash equality. A locally-present archive
225			// could be stale if another machine updated it via rotation conflict recovery,
226			// but that's unlikely and the checkpoints are still on /main regardless.
227			if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
228				remoteOnly = append(remoteOnly, suffix)
229			}
230		}
231	
232		sort.Strings(remoteOnly)
233		return remoteOnly, nil
234	}
235	
236	// handleRotationConflict handles the case where remote /full/current was rotated.
237	// Merges local /full/current into the latest remote archived generation to avoid
238	// duplicating checkpoint data, then adopts remote's /full/current as local.
239	func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
240		// Use the latest remote-only archive
241		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
242		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
243	
244		// Fetch the latest archived generation
245		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
246		archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
247		fetchCmd := CheckpointGitCommand(ctx, target, "fetch", target, archiveRefSpec)
248		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
249		if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
250			return fmt.Errorf("fetch archived generation failed: %s", output)
251		}
252		defer func() {
253			_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
254		}()
255	
256		// Get archived generation state
257		archiveRef, err := repo.Reference(archiveTmpRef, true)
258		if err != nil {
259			return fmt.Errorf("failed to get archived ref: %w", err)
260		}
261		archiveCommit, err := repo.CommitObject(archiveRef.Hash())
262		if err != nil {
263			return fmt.Errorf("failed to get archive commit: %w", err)
