		// could be stale if another machine updated it via rotation conflict recovery,
		// but that's unlikely and the checkpoints are still on /main regardless.
		if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
			remoteOnly = append(remoteOnly, suffix)
		}
	}

	sort.Strings(remoteOnly)
	return remoteOnly, nil
}

// handleRotationConflict handles the case where remote /full/current was rotated.
// Merges local /full/current into the latest remote archived generation to avoid
// duplicating checkpoint data, then adopts remote's /full/current as local.
func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
	// Use the latest remote-only archive
	latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
	archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)

	// Fetch the latest archived generation
	archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
	archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
	fetchCmd := CheckpointGitCommand(ctx, target, "fetch", target, archiveRefSpec)
	fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
	if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
		return fmt.Errorf("fetch archived generation failed: %s", output)
	}
	defer func() {
		_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
	}()

	// Get archived generation state
	archiveRef, err := repo.Reference(archiveTmpRef, true)
	if err != nil {
		return fmt.Errorf("failed to get archived ref: %w", err)
	}
	archiveCommit, err := repo.CommitObject(archiveRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get archive commit: %w", err)
	}
	archiveTree, err := archiveCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get archive tree: %w", err)
	}

	// Get local /full/current state
	localRef, err := repo.Reference(refName, true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}
	localCommit, err := repo.CommitObject(localRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get local commit: %w", err)
	}
	localTree, err := localCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get local tree: %w", err)
	}

	// Tree-merge local /full/current into archived generation.
	// Git content-addressing deduplicates shared shard paths automatically.
	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten archive tree: %w", err)
	}
	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten local tree: %w", err)
	}

	// Update generation.json timestamps if present in the merged tree.
	// Use the local /full/current HEAD commit time as the newest checkpoint time
	// (more accurate than time.Now() for cleanup scheduling).
	if genEntry, exists := entries[paths.GenerationFileName]; exists {
		if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
			entries[paths.GenerationFileName] = updatedEntry
		} else {
			logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
				slog.String("error", updateErr.Error()),
			)
		}
	}

	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build merged tree: %w", err)
	}

	// Create commit parented on archive's commit (fast-forward)
	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
		[]plumbing.Hash{archiveRef.Hash()},
		"Merge local checkpoints into archived generation")
	if err != nil {
		return fmt.Errorf("failed to create merge commit: %w", err)
	}

	// Update local archived ref and push it
	newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
	if err := repo.Storer.SetReference(newArchiveRef); err != nil {
		return fmt.Errorf("failed to update archive ref: %w", err)
	}

	if pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
		return fmt.Errorf("failed to push updated archive: %w", pushErr)
	}

	// Adopt remote's /full/current as local
	remoteRef, err := repo.Reference(tmpRefName, true)
	if err != nil {
		return fmt.Errorf("failed to get fetched /full/current: %w", err)
	}
	adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
	if err := repo.Storer.SetReference(adoptedRef); err != nil {
		return fmt.Errorf("failed to adopt remote /full/current: %w", err)
	}

	return nil
}

// updateGenerationTimestamps reads generation.json from a blob, updates
// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
// an updated tree entry. Uses the local commit timestamp rather than
// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
	blob, err := repo.BlobObject(genBlobHash)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
	}
	reader, err := blob.Reader()
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
	}
	defer reader.Close()

	data, err := io.ReadAll(reader)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
	}

	var gen checkpoint.GenerationMetadata
	if err := json.Unmarshal(data, &gen); err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
	}

	if newestFromLocal.After(gen.NewestCheckpointAt) {
		gen.NewestCheckpointAt = newestFromLocal
	}

	updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
	}

	newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
	}

	return object.TreeEntry{
		Name: paths.GenerationFileName,
		Mode: filemode.Regular,
		Hash: newBlobHash,
	}, nil
}

// pushV2Refs pushes v2 checkpoint refs to the target.
// Pushes /main, /full/current, and the latest archived generation (if any).
// Older archived generations are immutable and were pushed when created.
func pushV2Refs(ctx context.Context, target string) {
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally

	// Push only the latest archived generation (most likely to be newly created)
	repo, err := OpenRepository(ctx)
	if err != nil {
		return
	}
	store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
	archived, err := store.ListArchivedGenerations()
	if err != nil || len(archived) == 0 {
		return
	}
	latest := archived[len(archived)-1]
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
}

// shortRefName returns a human-readable short form of a ref name for log output.
// e.g., "refs/entire/checkpoints/v2/main" -> "v2/main"
func shortRefName(refName plumbing.ReferenceName) string {
	const prefix = "refs/entire/checkpoints/"
	s := string(refName)
	if strings.HasPrefix(s, prefix) {
		return s[len(prefix):]
	}
	return s
}

package strategy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
// The target can be a remote name (e.g., "origin") or a URL for direct push.
// When pushing to a URL, the "has unpushed" optimization is skipped since there are
// no remote tracking refs — git itself handles the no-op case.
// Does not check any settings — callers are responsible for gating.
func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Check if branch exists locally
	branchRef := plumbing.NewBranchReferenceName(branchName)
	localRef, err := repo.Reference(branchRef, true)
	if err != nil {
		// No branch, nothing to push
		return nil //nolint:nilerr // Expected when no sessions exist yet
	}

	// Only check remote tracking refs when target is a remote name (not a URL).
	// URLs don't have tracking refs, so we always attempt the push and let git handle it.
	if !isURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
		return nil
	}

	return doPushBranch(ctx, target, branchName)
}

// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
	// Check for remote tracking ref: refs/remotes/<remote>/<branch>
	remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
	remoteRef, err := repo.Reference(remoteRefName, true)
	if err != nil {
		// Remote branch doesn't exist yet - we have content to push
		return true
	}

	// If local and remote point to same commit, nothing to sync
	// This is the only case where we skip - any difference needs handling
	return localHash != remoteRef.Hash()
}

// doPushBranch pushes the given branch to the target with fetch+merge recovery.
// The target can be a remote name or a URL.
func doPushBranch(ctx context.Context, target, branchName string) error {
	displayTarget := target
	if isURL(target) {
		displayTarget = "checkpoint remote"
	}

	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
	stop := startProgressDots(os.Stderr)

	// Try pushing first
	if err := tryPushSessionsCommon(ctx, target, branchName); err == nil {
		stop(" done")
		printSettingsCommitHint(ctx, target)
		return nil
	}
	stop("")

	// Push failed - likely non-fast-forward. Try to fetch and merge.
	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
	stop = startProgressDots(os.Stderr)

	if err := fetchAndMergeSessionsCommon(ctx, target, branchName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
		printCheckpointRemoteHint(target)
		return nil // Don't fail the main push
	}
	stop(" done")

	// Try pushing again after merge
	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
	stop = startProgressDots(os.Stderr)

	if err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
		printCheckpointRemoteHint(target)
	} else {
		stop(" done")
		printSettingsCommitHint(ctx, target)
	}

	return nil
}

// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
// Only prints when the target is a URL (not the user's default remote).
func printCheckpointRemoteHint(target string) {
	if !isURL(target) {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
	fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
}

// printSettingsCommitHint prints a one-time hint after a successful checkpoint remote push
// when .entire/settings.json is not tracked by git. entire.io needs the committed settings
// to discover the external checkpoint repo.
func printSettingsCommitHint(ctx context.Context, target string) {
	if !isURL(target) {
		return
	}
	if isSettingsTrackedByGit(ctx) {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] Note: Commit and push .entire/settings.json for entire.io to discover your remote checkpoint.")
}

// isSettingsTrackedByGit returns true if .entire/settings.json is tracked by git.
func isSettingsTrackedByGit(ctx context.Context) bool {
	cmd := exec.CommandContext(ctx, "git", "ls-files", ".entire/settings.json")
	output, err := cmd.Output()
	if err != nil {
		return false
	}
	return len(strings.TrimSpace(string(output))) > 0
}

// tryPushSessionsCommon attempts to push the sessions branch.
func tryPushSessionsCommon(ctx context.Context, remote, branchName string) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Use --no-verify to prevent recursive hook calls
	cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", remote, branchName)

	output, err := cmd.CombinedOutput()
	if err != nil {
		// Check if it's a non-fast-forward error (we can try to recover)
		if strings.Contains(string(output), "non-fast-forward") ||
			strings.Contains(string(output), "rejected") {
			return errors.New("non-fast-forward")
		}
		return fmt.Errorf("push failed: %s", output)
	}
	return nil
}

// fetchAndMergeSessionsCommon fetches remote sessions and merges into local using go-git.
// Since session logs are append-only (unique cond-* directories), we just combine trees.
// The target can be a remote name or a URL.
func fetchAndMergeSessionsCommon(ctx context.Context, target, branchName string) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Determine fetch refspec. When target is a URL, use a temp ref;
	// when it's a remote name, use the standard remote-tracking ref.
	var fetchedRefName plumbing.ReferenceName
	var refSpec string
	if isURL(target) {
		tmpRef := "refs/entire-fetch-tmp/" + branchName
		refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
		fetchedRefName = plumbing.ReferenceName(tmpRef)
	} else {
		refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
		fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
	}

	// Use git CLI for fetch (go-git's fetch can be tricky with auth)
	fetchCmd := CheckpointGitCommand(ctx, target, "fetch", target, refSpec)
	if output, err := fetchCmd.CombinedOutput(); err != nil {
		return fmt.Errorf("fetch failed: %s", output)
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Reconcile disconnected metadata branches before merging trees.
	// The fetch above updated the remote-tracking ref, so reconciliation
	// can compare fresh local vs remote. If disconnected (empty-orphan bug),
	// this cherry-picks local commits onto remote tip, updating the local ref.
	// If reconciliation fails, abort — proceeding to tree merge on disconnected
	// branches would silently combine unrelated histories.
	if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, os.Stderr); reconcileErr != nil {
		return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
	}

	// Get local branch (re-read after potential reconciliation update)
	localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}
	localCommit, err := repo.CommitObject(localRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get local commit: %w", err)
	}
	localTree, err := localCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get local tree: %w", err)
	}

	// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
	remoteRef, err := repo.Reference(fetchedRefName, true)
	if err != nil {
		return fmt.Errorf("failed to get remote ref: %w", err)
	}
	remoteCommit, err := repo.CommitObject(remoteRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get remote commit: %w", err)
	}
	remoteTree, err := remoteCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get remote tree: %w", err)
	}

	// Flatten both trees and combine entries
	// Session logs have unique cond-* directories, so no conflicts expected
	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten local tree: %w", err)
	}
	if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten remote tree: %w", err)
	}

	// Build merged tree
	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build merged tree: %w", err)
	}

	// Create merge commit with both parents
	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
		[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
		"Merge remote session logs")
	if err != nil {
		return fmt.Errorf("failed to create merge commit: %w", err)
	}

	// Update branch ref
	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), mergeCommitHash)
	if err := repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch ref: %w", err)
	}

	// Clean up temp ref if we used one (best-effort, not critical if it fails)
	if isURL(target) {
		_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
	}

	return nil
}

// startProgressDots prints dots to w every second until the returned stop function
// is called. The stop function prints the given suffix and a newline.
func startProgressDots(w io.Writer) func(suffix string) {
	done := make(chan struct{})
	stopped := make(chan struct{})
	go func() {
		defer close(stopped)
		ticker := time.NewTicker(time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-done:
				return
			case <-ticker.C:
				fmt.Fprint(w, ".")
			}
		}
	}()
	return func(suffix string) {
		close(done)
		<-stopped // Wait for goroutine to finish before writing suffix
		fmt.Fprintln(w, suffix)
	}
}

// isURL returns true if the target looks like a URL rather than a git remote name.
func isURL(target string) bool {
	return strings.Contains(target, "://") || strings.Contains(target, "@")
}

// createMergeCommitCommon creates a merge commit with multiple parents.
func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
	authorName, authorEmail := GetGitAuthorFromRepo(repo)
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: parents,
		Author:       sig,
		Committer:    sig,
		Message:      message,
	}

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

